-- Kaldırma aksesuarları talimatı: periyodik kontrol yılda en az bir kez (kullanıcı kararı 12.11.2026)
-- Kütüphane + firmalara eklenmiş ve sonradan düzenlenmemiş kopyalar.

USE `u2858154_mehse`;

UPDATE `talimat_sablonlari` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, sapan, zincir, çelik halat ve mapa gibi kaldırma aksesuarlarının TS EN 13414 ve TS EN 818 standartları ile 6331 sayılı İş Sağlığı ve Güvenliği Kanunu çerçevesinde güvenli kullanımını, periyodik kontrollerini ve bakım esaslarını belirlemek amacıyla hazırlanmıştır.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Mekanik risklere ve kesilmelere karşı koruyucu iş eldiveni (TS EN 388) kullanılmalıdır.\",\"Darbe ve ezilmelere karşı çelik burunlu emniyet ayakkabısı (TS EN ISO 20345) giyilmelidir.\",\"Baş yaralanmalarını önlemek amacıyla endüstriyel baret (TS EN 397) takılmalıdır.\",\"Yüksekte yürütülen sapancı ve işaretçi çalışmalarında tam vücut emniyet kemeri (TS EN 361) kullanılmalıdır.\",\"Gözleri uçuşan parçacıklardan korumak için koruyucu gözlük (TS EN 166) takılmalıdır.\",\"Saha çalışmasında yüksek görünürlük sağlamak için ikaz yeleği (TS EN ISO 20471) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırma aksesuarının güvenli çalışma yükü (WLL) etiketi ve periyodik kontrol rengi kontrol edilmelidir.\",\"Çelik halat sapanlarda ezilme, kopuk tel, korozyon veya kuş yuvalanması deformasyonu incelenmelidir.\",\"Zincir sapan baklalarında aşınma, çatlak, uzama veya TS EN 818 standart dışı deformasyon kontrol edilmelidir.\",\"Mapaların pimi, diş yapısı ve emniyet kopilyasının eksiksiz ve uygun boyutta olduğu doğrulanmalıdır.\",\"Bez ve dokuma sapanlarda lif kopması, kesik, yanık veya kimyasal yıpranma kontrol edilmelidir.\",\"Kaldırılacak yükün ağırlığı ve ağırlık merkezi belirlenerek uygun açı ve kapasitede aksesuar seçilmelidir.\",\"Keskin kenarlı yüklerde sapanların zedelenmesini önlemek için uygun köşe koruyucu aparatlar yerleştirilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Sapan açıları dikkate alınmalı, sapan kolları arasındaki tepe açısı 120 dereceyi kesinlikle geçmemelidir.\",\"Kancaya takılan sapan halkalarının emniyet mandalını tam kapatacak şekilde oturduğu doğrulanmalıdır.\",\"Mapalar tam torkunda sıkılmalı ve eksenel olmayan yan yüklemelere maruz bırakılmamalıdır.\",\"Yük kaldırılırken sapan gerginliği kademeli olarak artırılmalı, ani kaldırma ve boşlama yapılmamalıdır.\",\"Yükün salınımını önlemek için kılavuz halatı kullanılmalı, yüke doğrudan elle müdahale edilmemelidir.\",\"Kaldırma esnasında aksesuarların birbiri üstüne biniş yapması veya burulması önlenmelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kullanım sonrası sapanlar, zincirler ve mapalar kir, yağ ve nemden arındırılarak temizlenmelidir.\",\"Aksesuarlar doğrudan güneş ışığı almayan, kuru ve korumalı alanlardaki özel askılıklarda muhafaza edilmelidir.\",\"Hasarlı, etiket bilgisi okunaksız veya standart dışı tespit edilen aksesuarlar derhal kullanımdan çekilmelidir.\",\"Kullanım dışı bırakılan aksesuarlara \'KULLANIMI TEHLİKELİDİR\' etiketi takılmalı ve yanlışlıkla kullanılmaması için ayrı (karantina) bölgede tutulmalıdır.\",\"Çelik halat ve zincir aksesuarlar imalatçı talimatlarına uygun olarak periyodik yağlama işlemine tabi tutulmalıdır.\",\"Aksesuarların periyodik kontrolleri yılda en az bir kez yetkili kişilere yaptırılmalı, kontrol raporu saklanmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Güvenli çalışma yükü (WLL) etiketi bulunmayan veya okunamayan aksesuarları kullanmak yasaktır.\",\"Kopuk tel sayısı sınırını aşmış çelik halatları ve baklalarında uzama olan zincirleri kullanmak yasaktır.\",\"Sapanlara düğüm atmak, cıvata ile zincir boyu kısaltmak veya kaynaklı tamirat yapmak yasaktır.\",\"Hasarlı, dişleri bozulmuş veya pimi orijinal olmayan mapaları kullanmak yasaktır.\",\"Sapan kolları arasında 120 dereceden fazla açı oluşturacak şekilde kaldırma yapmak yasaktır.\",\"Keskin kenarlı yüklere koruyucu ped veya aparat takmadan sapan bağlamak yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Aksesuar kayması veya deformasyon riski görüldüğünde çalışma derhal durdurulmalıdır.\",\"Tehlikeli durum ve aksesuar arızaları vakit kaybetmeksizin birim amirine ve İSG birimine bildirilmelidir.\",\"Yük düşmesi veya devrilmesi durumunda alan derhal emniyet şeridine alınarak erişim kısıtlanmalıdır.\",\"Yaralanmalı kazalarda ilk yardım müdahalesi yapılarak 112 Acil Çağrı Merkezi bilgilendirilmelidir.\",\"Kazaya veya tehlikeye neden olan aksesuar ve olay yeri inceleme tamamlanana kadar korunmalıdır.\"]}]', `updated_at` = NOW() WHERE `ekipman_tipi` = 'Kaldırma Aksesuarları (sapan, zincir, halat, mapa)';
UPDATE `talimatlar` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, sapan, zincir, çelik halat ve mapa gibi kaldırma aksesuarlarının TS EN 13414 ve TS EN 818 standartları ile 6331 sayılı İş Sağlığı ve Güvenliği Kanunu çerçevesinde güvenli kullanımını, periyodik kontrollerini ve bakım esaslarını belirlemek amacıyla hazırlanmıştır.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Mekanik risklere ve kesilmelere karşı koruyucu iş eldiveni (TS EN 388) kullanılmalıdır.\",\"Darbe ve ezilmelere karşı çelik burunlu emniyet ayakkabısı (TS EN ISO 20345) giyilmelidir.\",\"Baş yaralanmalarını önlemek amacıyla endüstriyel baret (TS EN 397) takılmalıdır.\",\"Yüksekte yürütülen sapancı ve işaretçi çalışmalarında tam vücut emniyet kemeri (TS EN 361) kullanılmalıdır.\",\"Gözleri uçuşan parçacıklardan korumak için koruyucu gözlük (TS EN 166) takılmalıdır.\",\"Saha çalışmasında yüksek görünürlük sağlamak için ikaz yeleği (TS EN ISO 20471) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırma aksesuarının güvenli çalışma yükü (WLL) etiketi ve periyodik kontrol rengi kontrol edilmelidir.\",\"Çelik halat sapanlarda ezilme, kopuk tel, korozyon veya kuş yuvalanması deformasyonu incelenmelidir.\",\"Zincir sapan baklalarında aşınma, çatlak, uzama veya TS EN 818 standart dışı deformasyon kontrol edilmelidir.\",\"Mapaların pimi, diş yapısı ve emniyet kopilyasının eksiksiz ve uygun boyutta olduğu doğrulanmalıdır.\",\"Bez ve dokuma sapanlarda lif kopması, kesik, yanık veya kimyasal yıpranma kontrol edilmelidir.\",\"Kaldırılacak yükün ağırlığı ve ağırlık merkezi belirlenerek uygun açı ve kapasitede aksesuar seçilmelidir.\",\"Keskin kenarlı yüklerde sapanların zedelenmesini önlemek için uygun köşe koruyucu aparatlar yerleştirilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Sapan açıları dikkate alınmalı, sapan kolları arasındaki tepe açısı 120 dereceyi kesinlikle geçmemelidir.\",\"Kancaya takılan sapan halkalarının emniyet mandalını tam kapatacak şekilde oturduğu doğrulanmalıdır.\",\"Mapalar tam torkunda sıkılmalı ve eksenel olmayan yan yüklemelere maruz bırakılmamalıdır.\",\"Yük kaldırılırken sapan gerginliği kademeli olarak artırılmalı, ani kaldırma ve boşlama yapılmamalıdır.\",\"Yükün salınımını önlemek için kılavuz halatı kullanılmalı, yüke doğrudan elle müdahale edilmemelidir.\",\"Kaldırma esnasında aksesuarların birbiri üstüne biniş yapması veya burulması önlenmelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kullanım sonrası sapanlar, zincirler ve mapalar kir, yağ ve nemden arındırılarak temizlenmelidir.\",\"Aksesuarlar doğrudan güneş ışığı almayan, kuru ve korumalı alanlardaki özel askılıklarda muhafaza edilmelidir.\",\"Hasarlı, etiket bilgisi okunaksız veya standart dışı tespit edilen aksesuarlar derhal kullanımdan çekilmelidir.\",\"Kullanım dışı bırakılan aksesuarlara \'KULLANIMI TEHLİKELİDİR\' etiketi takılmalı ve yanlışlıkla kullanılmaması için ayrı (karantina) bölgede tutulmalıdır.\",\"Çelik halat ve zincir aksesuarlar imalatçı talimatlarına uygun olarak periyodik yağlama işlemine tabi tutulmalıdır.\",\"Aksesuarların periyodik kontrolleri yılda en az bir kez yetkili kişilere yaptırılmalı, kontrol raporu saklanmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Güvenli çalışma yükü (WLL) etiketi bulunmayan veya okunamayan aksesuarları kullanmak yasaktır.\",\"Kopuk tel sayısı sınırını aşmış çelik halatları ve baklalarında uzama olan zincirleri kullanmak yasaktır.\",\"Sapanlara düğüm atmak, cıvata ile zincir boyu kısaltmak veya kaynaklı tamirat yapmak yasaktır.\",\"Hasarlı, dişleri bozulmuş veya pimi orijinal olmayan mapaları kullanmak yasaktır.\",\"Sapan kolları arasında 120 dereceden fazla açı oluşturacak şekilde kaldırma yapmak yasaktır.\",\"Keskin kenarlı yüklere koruyucu ped veya aparat takmadan sapan bağlamak yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Aksesuar kayması veya deformasyon riski görüldüğünde çalışma derhal durdurulmalıdır.\",\"Tehlikeli durum ve aksesuar arızaları vakit kaybetmeksizin birim amirine ve İSG birimine bildirilmelidir.\",\"Yük düşmesi veya devrilmesi durumunda alan derhal emniyet şeridine alınarak erişim kısıtlanmalıdır.\",\"Yaralanmalı kazalarda ilk yardım müdahalesi yapılarak 112 Acil Çağrı Merkezi bilgilendirilmelidir.\",\"Kazaya veya tehlikeye neden olan aksesuar ve olay yeri inceleme tamamlanana kadar korunmalıdır.\"]}]', `updated_at` = NOW() WHERE `baslik` = 'KALDIRMA AKSESUARLARI (SAPAN, ZİNCİR, HALAT, MAPA) GÜVENLİ ÇALIŞMA TALİMATI' AND `aciklama` = 'Uzman onaylı (12.11.2026)';

-- Doğrulama: beklenen  1
SELECT COUNT(*) AS guncel FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Kaldırma Aksesuarları (sapan, zincir, halat, mapa)' AND `bolumler` LIKE '%en az bir kez yetkili%';
